// Card data, generated by `pnpm update-cards` into generated/. Stats files
// load on demand, so the browser only downloads the selected server's stats.
import metadata from "../generated/metadata.js"
import { joinCards } from "./join-cards.js"

export { metadata }

const STATS = {
  gl: () => import("../generated/global_stats.js"),
  jp: () => import("../generated/jp_stats.js"),
}

const cache = {}

// Same shape and order as upstream's src/cards/gl.js and jp.js arrays.
export function loadCards(server) {
  cache[server] ??= STATS[server]().then((m) => joinCards(server, metadata, m.default))
  return cache[server]
}
